from author import *
bio='范总管是《卖命》《考验》中非人协会的年老事务负责人，协调整个生命配额研究计划。他和会员借个人飞行器出现，并不是自己可以凭空飞行；交流时不善把复杂事情说清，常需要白素提醒从头叙述。他对卫斯理寻根究底颇有成见，也曾借未获入会奚落对方，后来被指出协会自身的信息不透明，才认真解释计划。'+'他希望把可转移的生命配额提供给真正推动科学和思想进步的人，不以多赚钱为目的。文依来兄弟救母的事件给他启发，但兄弟只会转移自身特殊配额，他不能把这个成功照搬成普通人的现成技术。通过黄而和水，他召集自愿应征者确认意愿，随后送回，研究仍未完成便先召开分配原则会议，并邀请白素加入决策委员会和协会。卡片保留理想、组织热情及过分相信自己善意的盲点，让他在参与者权益、分配权监督和保密之间作出具体选择；善意不等于无需解释，古堡资源也不是个人超能。原作未明确回指早期无名总管的身世，本卡暂作为该时期明确姓范的负责人记录。'
tr=[('外界把研究理解为给富豪买命','认为善意遭到误会','解释目的，但应先承认公开启事确实容易造成误解。'),('有机会延长有贡献者的生命','技术尚未成熟','积极组织研究与分配讨论，不把信心当成已成功。'),('受邀者追问保密和自主意愿','质疑使自己不耐烦','仍须说明条件、允许退出，并面对分配权带来的监督。')]
c=human('fan_zongguan','范总管',bio,'在《考验》中继续组织生命配额分配原则讨论；技术仍在研究，没有证实普遍转移成功。','协会事务组织、交涉与研究协调，实际拥有时可用个人飞行器；没有独立转移寿命的能力。','让有贡献的生命获得更多发展时间，维护协会合作与研究。',tr,[ev(120,2357,2382,'飞行器与负责人'),ev(120,2499,2538,'冲突与解释'),ev(120,2554,2643,'理想、邀请与研究边界'),ev(121,27,40,'继续讨论'),ev(121,120,136,'当前会员与漫长会议')],roles=['跨书重要配角'])
c['uncertainties']=['与非人协会早期无名总管是否同一人，正文未作明确身世回指；不与早期会员范先生仅凭同姓合并。']
c['aliases']=['范总管（配额研究）']
base=[WEI,BAI]+[(n,'weisili_'+k,'重要配角','实际参与配额调查')for k,n in [('wen_baoyu','温宝裕'),('hong_ling','红绫'),('xiao_guo','小郭'),('da_heng','大亨'),('tao_qiquan','陶启泉'),('zhu_jin','朱槿'),('liang_sheng','亮声')]]
cv119=cov(119,base+[(n,i,'跨系列主角','调查或委托')for n,i in [('康维','yuanzhenxia_kangwei'),('柳絮','yuanzhenxia_liu_xu'),('水荭','adventure_shui_hong')]]+[(n,'weisili_'+k,'重要配角','具体交流')for k,n in [('lao_cai','老蔡'),('ge_bi','戈壁'),('sha_mo','沙漠'),('song_tianran','宋天然（宋自然）')]], [('各地收信三人小组','未个体化的受雇执行人；没有证据证明掌握核心技术或主动施害。'),('匿名买家及代表','推动市场需求的背景群体，具名大亨、陶启泉及后续陈氏兄弟已合并主卡。'),('应征者','大规模被研究者，不将贫困或自愿出让配额者自动归类为反派。')],['119未解谜底由120–121回写：视觉异常出于水的脑部干预，不能停在立体投影假说。'])
cv120=cov(120,base+[(n,i,'跨系列主角','实际调查与交流')for n,i in [('康维','yuanzhenxia_kangwei'),('柳絮','yuanzhenxia_liu_xu'),('陈景德','yuanzhenxia_chen_jingde'),('陈宜兴','yuanzhenxia_chen_yixing')]]+[(n,'weisili_'+k,'重要配角','联络、实验或回述行动')for k,n in [('liang_chen','良辰'),('mei_jing','美景'),('huang_er','黄而'),('water_life','水'),('wen_yilai','文依来'),('wen_yilai_brother','文依来兄弟中的另一位')]]+[(c['name'],c['id'],'重要配角','研究负责人')],[('其他六位当期非人会员','未明确身份，不按七人数目自动套入早期会员名单；共同会议不据此虚构个人能力。'),('文依来兄弟之母','救母旧事承接既有角色，后期证据并入负责电王人物的主卡。'),('原有多名匿名应征者','无独立人物线，不将水的干预算作他们的个人能力。')],['陈氏兄弟120–121能正常交流，085损伤如何恢复未述；以较后实际表现更新，不杜撰治疗。','是否同意配额转移必须与水对途中意识的控制分开，不能把被控制后的行为当作原初自愿的证据。'])
save('part_c',[c],[cv119,cv120])
